%[text] ## More...

% les formes fourier au lieu de Toepliz
S.F_bt %[output:67c42495]
S.F_tb  %[output:44c54970]


%forme Fourier vec en TB
S.FvTB(h) %[output:5d993fac]
S{:}.F_tb %[output:887eec8c]

%TB2Array converti une matrice TB, dont on connait le nombre de bloc, pour
%en reconstruite le phasorArray 3D
TB2array(A.T_tb(h),size(A,1))  %[output:64b2b934]


sum(A,1) %[output:75be5a09]
permute(A,[2 1]) %[output:780f6371]
size(A,1) %[output:5b295120]
size(A,2) %[output:0492bd26]
numel(A) %[output:867c050b]
numelt(A) %[output:5c85f358]

angle=1.57 %rad %[output:228ad544]
evalp(A,angle) %[output:80a15ca1]

B=rand_phasor(3,1,7,'output','PhasorArray') %[output:6cce9a75]
iscolumn(B) %[output:1b842a0e]
isrow(B) %[output:2a6f198d]
isrow(B.') %[output:7446f925]
ismatrix(B) %[output:0e22be3a]
issquare(B) %[output:6b65da4d]

C=rand_phasor(1,1,8,'output','PhasorArray') %[output:541c0d01]
isscalar(C) %[output:97cd1b2d]

issquare(A) %[output:320aa700]

figure %[output:97980a98]
plot(A) %[output:97980a98]
figure %[output:6aec7843]
plot(retro(A)) %[output:6aec7843]

